#include <stdio.h>
int main(void) {
  FILE *file = fopen("records.txt", "w+");
  if (!file) return 1;
  fprintf(file, "12 80\n7 95\n");
  rewind(file);
  int id, score, count = 0, sum = 0;
  while (fscanf(file, "%d %d", &id, &score) == 2) {
    count++;
    sum += score;
  }
  fclose(file);
  printf("count=%d,sum=%d\n", count, sum);
  return 0;
}

