#include <stdio.h>
int main(void) {
  int n;
  if (scanf("%d", &n) != 1 || n < 0 || n > 8) return 1;
  FILE *file = fopen("values.txt", "w+");
  if (!file) return 2;
  for (int i = 0; i < n; i++) {
    int value;
    if (scanf("%d", &value) != 1) { fclose(file); return 3; }
    if (fprintf(file, "%d\n", value) < 0) { fclose(file); return 4; }
  }
  rewind(file);
  int count = 0, sum = 0, value;
  while (fscanf(file, "%d", &value) == 1) { count++; sum += value; }
  fclose(file);
  printf("count=%d,sum=%d\n", count, sum);
  return 0;
}
